        a = (1.0f - d->t) * ((*(float *)&two_door_gate_open_angle_deg) * 0.017453292f);
        d->left->rot.y = a;
        d->right->rot.y = a;
        moby_build_matrix(d->left);
        moby_build_matrix(d->right);
        if (d->t >= 1.0f) {
            d->t = 0.0f;
            moby->state = 4;
        }
        break;
